import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent (if provided, must be valid)
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }
    const discountPercent = line.discountPercent ?? 0;

    // Validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents(total * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
  }
  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  const total = Math.max(0, roundCents(subtotal - discount));
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent (if provided, must be valid)
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }
  const discount = discountPercent ?? 0;

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Find existing line
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    // Line exists, increase qty
    newLines = invoice.lines.map((line, index) =>
      index === existingLineIndex ? { ...line, qty: line.qty + qty } : line,
    );
  } else {
    // New line
    const product = productResult.value;
    newLines = [
      ...invoice.lines,
      {
        sku,
        name: product.name,
        qty,
        unitPrice: product.unitPrice,
        vatRate: product.vatRate,
        discountPercent: discount,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, number?: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

function isValidDate(dateString) {
  // Check format YYYY-MM-DD
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(dateString)) return false;

  // Check if it's a valid date
  const date = new Date(dateString + 'T00:00:00Z');
  if (Number.isNaN(date.getTime())) return false;

  // Check if the date actually corresponds to the input string
  const [year, month, day] = dateString.split('-').map(Number);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() + 1 === month &&
    date.getUTCDate() === day
  );
}

