    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 5 × 8500 = 42500
      { sku: 'DEV-HOUR', qty: 3 }, // 3 × 9500 = 28500
    ],
