test('invoiceTotals includes subtotal, discount, and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 10 }, // 425.00 - 42.50 = 382.50
      { qty: 3, unitPrice: 9500, discountPercent: 0 }, // 285.00 - 0 = 285.00
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 71000); // 425 + 285 = 710
  assert.equal(totals.discount, 4250); // 42.50
  assert.equal(totals.total, 66750); // 710 - 42.50 = 667.50
});

